/bin/bash -lc "python - <<'PY'
import os, requests, urllib.parse
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
id_='toolshed.g2.bx.psu.edu/repos/bgruening/text_processing/tp_sort_rows/9.5+galaxy3'
d=requests.get(url+'/api/tools/'+urllib.parse.quote(id_, safe=''), params={'key':key,'io_details':True}, timeout=30).json()
print('name',d.get('name'),d.get('version'))

def walk(inputs, prefix=''):
    for inp in inputs:
        typ=inp.get('type'); name=inp.get('name'); p=prefix+name
        if typ=='conditional':
            print(p,'COND test', inp.get('test_param',{}).get('name'), 'default', inp.get('test_param',{}).get('value'), 'cases',[c.get('value') for c in inp.get('cases',[])])
            for c in inp.get('cases',[]): walk(c.get('inputs',[]), p+'|'+c.get('value')+'|')
        elif typ=='repeat':
            print(p,'REPEAT')
            walk(inp.get('inputs',[]), p+'[]|')
        elif typ=='section':
            print(p,'SECTION')
            walk(inp.get('inputs',[]), p+'|')
        else:
            print(p, typ, 'default=',inp.get('value'), 'optional=',inp.get('optional'), 'label=',inp.get('label'))
            if typ=='select': print(' opts=',inp.get('options'))
walk(d.get('inputs',[]))
PY"
